<?php if(session('erro')): ?><div style="color:red;text-align:center;margin:10px 0;font-weight:bold"><?php echo e(session('erro')); ?></div><?php endif; ?>
<div class="bg-white w-full max-w-md mx-auto rounded-lg drop-shadow-lg mt-22 px-4 md:px-10 py-10 h-auto"><form action="<?php echo e(route('atrasos.registrar')); ?>" method="post" id="cadastroForm" class="flex flex-col justify-center items-center mt-4" onsubmit="return prepararEnvio()"><?php echo csrf_field(); ?><div class="w-full pesquisa"><input class="border border-gray-400 rounded-md p-3 mb-2 w-full" type="text" id="nome" name="nome" placeholder="Nome Completo" required autocomplete="off" onkeyup="buscarNomes()" onblur="validarNome()"><input type="hidden" id="turma" name="turma"><div id="mensagemErro"></div><div id="sugestoes" class="sugestoes"></div></div><select class="border border-gray-400 rounded-md p-3 mb-5 w-full" id="motivo_atraso" name="motivo_atraso" required onchange="mostrarCaixaTexto()"><option value="">Motivo do Atraso</option><option>Perdi o horário</option><option>Chuva</option><option>Imprevisto com o meio de transporte</option><option>Outro</option></select><div id="outro_motivo" class="w-full mb-5 hidden"><input class="border border-gray-400 rounded-md p-3 w-full" type="text" id="outro_text" name="outro_text" placeholder="Especifique o Motivo"></div><div class="text-center"><button class="bg-marista text-white px-6 py-2 rounded-lg drop-shadow-lg mt-2">GERAR BILHETE</button></div></form></div>
<footer class="bg-marista text-center py-3 mt-35"><p class="text-sm text-gray-500">Criado por <strong class="text-gray-700">Eduardo Machado Ferla</strong> e <strong class="text-gray-700">Gabrielly Heloyse Oviedo</strong> | <span class="italic">Projeto SOS Atraso</span></p><small class="block text-xs text-gray-400 mt-1">&copy; <?php echo e(date('Y')); ?> Todos os direitos reservados a Marista Escola Social Cascavel | <a href="<?php echo e(route('admin.login')); ?>">Admin</a></small></footer>
<script>let timer;function buscarNomes(){clearTimeout(timer);let q=nome.value.trim();if(q.length<2){sugestoes.innerHTML='';return}timer=setTimeout(()=>fetch('<?php echo e(route('alunos.buscar')); ?>?nome='+encodeURIComponent(q)).then(r=>r.json()).then(d=>{sugestoes.innerHTML=d.map(a=>`<div onmousedown="selecionarNome('${String(a.nome).replace(/'/g,"\\'")}|${a.turma}')">${a.nome}</div>`).join('')}),200)}function selecionarNome(v){let p=v.split('|');nome.value=p[0];turma.value=p[1];sugestoes.innerHTML='';mensagemErro.innerText=''}function mostrarCaixaTexto(){let o=motivo_atraso.value==='Outro';outro_motivo.classList.toggle('hidden',!o);outro_text.required=o;if(!o)outro_text.value=''}function validarNome(){if(!nome.value.trim())return;fetch('<?php echo e(route('alunos.buscar')); ?>?validar=1&nome='+encodeURIComponent(nome.value.trim())).then(r=>r.text()).then(t=>{if(t.trim()==='invalido'){mensagemErro.innerText='⚠ Nome não encontrado. Selecione um aluno válido!';nome.value='';turma.value=''}})}function prepararEnvio(){if(!nome.value.trim()||!turma.value.trim()){mensagemErro.innerText='⚠ Selecione um aluno válido na lista!';return false}return true}</script>
<?php $__env->stopSection(); ?>

